insert into public.announcements (id,organization_id,created_at,updated_at,property_id,title,body,category,published_at) values ('0000000e-0000-4000-8000-000000000001','00000001-0000-4000-8000-000000000001','2026-09-17T09:00:00Z','2026-09-17T09:00:00Z','00000002-0000-4000-8000-000000000001','A little coffee, a little community','Join your neighbors in the courtyard on Saturday, September 19, from 9–11 AM. Coffee and pastries are on us. We look forward to seeing you there!','Community','2026-09-16T09:00:00Z') on conflict (id) do nothing;
insert into public.announcements (id,organization_id,created_at,updated_at,property_id,title,body,category,published_at) values ('0000000e-0000-4000-8000-000000000002','00000001-0000-4000-8000-000000000001','2026-09-17T09:00:00Z','2026-09-17T09:00:00Z',null,'Your fall community update','Fall landscaping starts September 21. Our crews will work between 9 AM and 4 PM. All entrances will remain accessible. Thank you for helping us keep your community beautiful.','Community','2026-09-14T09:00:00Z') on conflict (id) do nothing;
insert into public.announcements (id,organization_id,created_at,updated_at,property_id,title,body,category,published_at) values ('0000000e-0000-4000-8000-000000000003','00000001-0000-4000-8000-000000000001','2026-09-17T09:00:00Z','2026-09-17T09:00:00Z','00000002-0000-4000-8000-000000000002','Pool care on September 22','The pool will be closed from 8 AM until noon for routine cleaning. The courtyard and fitness studio remain open.','Maintenance','2026-09-15T09:00:00Z') on conflict (id) do nothing;
insert into public.announcements (id,organization_id,created_at,updated_at,property_id,title,body,category,published_at) values ('0000000e-0000-4000-8000-000000000004','00000001-0000-4000-8000-000000000001','2026-09-17T09:00:00Z','2026-09-17T09:00:00Z','00000002-0000-4000-8000-000000000001','A fresh start for the parking lot','Parking spaces 1–12 will be resurfaced Tuesday, September 22, between 9 AM and 4 PM. Please use the marked visitor spaces during this time. All building entrances will remain accessible.','Maintenance','2026-09-17T09:00:00Z') on conflict (id) do nothing;
insert into public.announcements (id,organization_id,created_at,updated_at,property_id,title,body,category,published_at) values ('0000000e-0000-4000-8000-000000000005','00000001-0000-4000-8000-000000000001','2026-09-17T09:00:00Z','2026-09-17T09:00:00Z',null,'A little fall care for your HVAC','A clean filter helps your home stay comfortable. If you would like help checking or replacing yours, send a Heating / Cooling maintenance request and our team will arrange a visit.','Home care','2026-09-15T09:00:00Z') on conflict (id) do nothing;
insert into public.announcements (id,organization_id,created_at,updated_at,property_id,title,body,category,published_at) values ('0000000e-0000-4000-8000-000000000006','00000001-0000-4000-8000-000000000001','2026-09-17T09:00:00Z','2026-09-17T09:00:00Z','00000002-0000-4000-8000-000000000001','Office closure on September 25','The leasing office will be closed Friday, September 25 for team training. Regular hours resume Monday at 9 AM. You can still leave a portal request; urgent issues should go through the after-hours maintenance line.','Office','2026-09-16T15:00:00Z') on conflict (id) do nothing;
